using System.Security.Cryptography;using System.Text;using System.Text.Json;using Npgsql;
namespace IcpaaS.Api;
public sealed class PlatformStore(IConfiguration configuration){readonly string _cs=configuration["ICPaaS:Database:ConnectionString"]??configuration.GetConnectionString("ICPaaS")??throw new InvalidOperationException("Database connection is required");public async Task<NpgsqlConnection> Open(CancellationToken ct){var c=new NpgsqlConnection(_cs);await c.OpenAsync(ct);return c;}public static string Hash(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();public static string Password(string password,string salt)=>Convert.ToHexString(Rfc2898DeriveBytes.Pbkdf2(password,Convert.FromBase64String(salt),210000,HashAlgorithmName.SHA256,32));public static string Salt()=>Convert.ToBase64String(RandomNumberGenerator.GetBytes(24));public static string Json(object value)=>JsonSerializer.Serialize(value);}
